create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,nickname text,created_at timestamptz default now());create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz default now());create table if not exists public.notices(id bigint generated by default as identity primary key,title text not null,content text not null default '',created_at timestamptz default now(),updated_at timestamptz default now());create table if not exists public.posts(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete set null,title text not null,content text not null default '',created_at timestamptz default now());alter table public.profiles enable row level security;alter table public.admins enable row level security;alter table public.notices enable row level security;alter table public.posts enable row level security;create policy "profiles own select" on public.profiles for select using(auth.uid()=id);create policy "admins own select" on public.admins for select using(auth.uid()=user_id);create policy "notices public read" on public.notices for select using(true);create policy "posts public read" on public.posts for select using(true);create policy "posts auth insert" on public.posts for insert with check(auth.uid()=user_id);